import os
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

import check_generated_diff

SCRIPT = Path(__file__).resolve().parent / 'check_generated_diff.py'

GENERATED_FILE = '''// Code generated by protoc-gen-go. DO NOT EDIT.
// versions:
// \tprotoc-gen-go {version}
// \tprotoc        v6.31.1
// source: run.proto

package client

type Run struct {{
\tName string
}}
'''

GRPC_FILE = '''// Code generated by protoc-gen-go-grpc. DO NOT EDIT.
// versions:
// - protoc-gen-go-grpc {version}
// - protoc             v6.31.1
// source: run.proto

package client
'''


class GeneratorStampTest(unittest.TestCase):

    def test_matches_both_generator_comment_styles(self):
        self.assertTrue(
            check_generated_diff.GENERATOR_STAMP.match(
                '// \tprotoc-gen-go v1.36.12'.strip()))
        self.assertTrue(
            check_generated_diff.GENERATOR_STAMP.match(
                '// - protoc-gen-go-grpc v1.6.2'.strip()))

    def test_ignores_the_protoc_version_line(self):
        # protoc is pinned by the toolchain, not by a Go module, so a change
        # there is a deliberate bump rather than Dependabot churn.
        self.assertIsNone(
            check_generated_diff.GENERATOR_STAMP.match(
                '// \tprotoc        v6.31.1'.strip()))

    def test_ignores_ordinary_comments_and_code(self):
        for line in ('// source: run.proto', 'type Run struct {',
                     '// Code generated by protoc-gen-go. DO NOT EDIT.'):
            self.assertIsNone(
                check_generated_diff.GENERATOR_STAMP.match(line.strip()), line)


class ChangedLinesTest(unittest.TestCase):

    def test_skips_diff_file_headers(self):
        diff = ('--- a/run.pb.go\n'
                '+++ b/run.pb.go\n'
                '@@ -3 +3 @@\n'
                '-// \tprotoc-gen-go v1.36.11-devel\n'
                '+// \tprotoc-gen-go v1.36.12\n')
        self.assertEqual(
            check_generated_diff.changed_lines(diff),
            ['// \tprotoc-gen-go v1.36.11-devel', '// \tprotoc-gen-go v1.36.12'],
        )

    def test_empty_diff_is_not_stamp_only(self):
        self.assertFalse(check_generated_diff.is_generator_stamp_only(''))


class WorktreeEntriesTest(unittest.TestCase):

    def test_parses_status_codes_and_paths(self):
        status = ' M api/run.pb.go\n?? api/new.pb.go\n D api/gone.pb.go\n'
        self.assertEqual(
            check_generated_diff.worktree_entries(status),
            [('M', 'api/run.pb.go'), ('??', 'api/new.pb.go'),
             ('D', 'api/gone.pb.go')],
        )

    def test_uses_the_destination_of_a_rename(self):
        self.assertEqual(
            check_generated_diff.worktree_entries('R  old.pb.go -> new.pb.go\n'),
            [('R', 'new.pb.go')],
        )


class EndToEndTest(unittest.TestCase):
    """Drive the script against a real repository, as CI does."""

    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        self.repository = Path(self.directory.name)
        self.addCleanup(self.directory.cleanup)
        self.git('init', '-q', '-b', 'main')
        self.git('config', 'user.email', 'test@example.com')
        self.git('config', 'user.name', 'Test')
        self.write('run.pb.go', GENERATED_FILE.format(version='v1.36.11-devel'))
        self.write('run_grpc.pb.go', GRPC_FILE.format(version='v1.6.2'))
        self.git('add', '-A')
        self.git('commit', '-qm', 'initial')

    def git(self, *arguments):
        subprocess.run(['git', *arguments],
                       cwd=self.repository,
                       check=True,
                       capture_output=True)

    def write(self, name, contents):
        (self.repository / name).write_text(contents, encoding='utf-8')

    def check(self):
        return subprocess.run([sys.executable, str(SCRIPT)],
                              cwd=self.repository,
                              capture_output=True,
                              text=True)

    def test_clean_tree_passes(self):
        self.assertEqual(self.check().returncode, 0)

    def test_generator_version_only_change_passes(self):
        self.write('run.pb.go', GENERATED_FILE.format(version='v1.36.12'))
        result = self.check()
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        self.assertIn('run.pb.go', result.stdout)
        self.assertIn('generated code itself is unchanged', result.stdout)

    def test_generator_version_change_passes_when_already_staged(self):
        # The generation step stages its output, which the previous `git diff`
        # based check could not see.
        self.write('run.pb.go', GENERATED_FILE.format(version='v1.36.12'))
        self.git('add', '-A')
        self.assertEqual(self.check().returncode, 0)

    def test_grpc_generator_version_only_change_passes(self):
        self.write('run_grpc.pb.go', GRPC_FILE.format(version='v1.7.0'))
        self.assertEqual(self.check().returncode, 0)

    def test_code_change_fails(self):
        self.write(
            'run.pb.go',
            GENERATED_FILE.format(version='v1.36.11-devel').replace(
                'Name string', 'Name string\n\tDescription string'))
        result = self.check()
        self.assertEqual(result.returncode, 1)
        self.assertIn('Generated files are out of date', result.stdout)

    def test_code_change_alongside_version_change_fails(self):
        self.write(
            'run.pb.go',
            GENERATED_FILE.format(version='v1.36.12').replace(
                'Name string', 'Name string\n\tDescription string'))
        self.assertEqual(self.check().returncode, 1)

    def test_failure_output_includes_staged_changes(self):
        self.write(
            'run.pb.go',
            GENERATED_FILE.format(version='v1.36.11-devel').replace(
                'Name string', 'Name string\n\tDescription string'))
        self.git('add', '-A')
        result = self.check()
        self.assertEqual(result.returncode, 1)
        self.assertIn('Description string', result.stdout)

    def test_new_generated_file_fails(self):
        self.write('extra.pb.go', GENERATED_FILE.format(version='v1.36.12'))
        result = self.check()
        self.assertEqual(result.returncode, 1)
        self.assertIn('extra.pb.go', result.stdout)

    def test_deleted_generated_file_fails(self):
        (self.repository / 'run.pb.go').unlink()
        self.assertEqual(self.check().returncode, 1)


if __name__ == '__main__':
    unittest.main()
